export function SubjectWorkloadPage({ subject, onBack }) {

    const isLectureBased = subject.formatOfDelivery === 'Lecture based';
    const pageTitle = `Subject Workload - ${isLectureBased ? 'Lecture Based' : 'Project Based'}`;
    const tabs = isLectureBased 
        ? ["Base Allocation", "Per-delivery Allocation", "Staff Roles", "Per-student Allocation", "Activity Allocation"]
        : ["Base Allocation", "Per-group Allocation"];

    const [activeTab, setActiveTab] = useState(tabs[0]);

    const styles = {
        container: { fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif', padding: '2rem', backgroundColor: '#f8f9fa', minHeight: '100vh' },
        header: { display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '1.5rem' },
        backButton: { background: 'none', border: '1px solid #dee2e6', borderRadius: '50%', width: '40px', height: '40px', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: '#495057' },
        pageTitle: { color: '#343a40', fontSize: '1.75rem', margin: 0 },
        mainContent: { display: 'flex', gap: '2rem' },
        stepperContainer: { flex: '0 0 200px' },
        stepper: { display: 'flex', flexDirection: 'column', gap: '1.5rem', position: 'relative' },
        stepperStep: { display: 'flex', alignItems: 'center', gap: '1rem' },
        stepperCircle: (isActive) => ({
            width: '24px', height: '24px', borderRadius: '50%',
            border: `2px solid ${isActive ? '#007bff' : '#adb5bd'}`,
            backgroundColor: isActive ? '#007bff' : 'transparent',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            position: 'relative', zIndex: 1
        }),
        stepperInnerCircle: { width: '8px', height: '8px', borderRadius: '50%', backgroundColor: 'white' },
        stepperLabel: (isActive) => ({ color: isActive ? '#343a40' : '#6c757d', fontWeight: isActive ? '600' : '400' }),
        stepperLine: { position: 'absolute', left: '12px', top: '24px', bottom: '24px', width: '2px', backgroundColor: '#e9ecef', zIndex: 0 },
        contentArea: { flex: 1 },
        infoCard: { backgroundColor: 'white', borderRadius: '8px', boxShadow: '0 2px 10px rgba(0,0,0,0.05)', padding: '1.5rem', marginBottom: '1.5rem' },
        infoGrid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '1rem' },
        infoItem: { display: 'flex', flexDirection: 'column' },
        infoLabel: { color: '#6c757d', fontSize: '0.9rem', marginBottom: '0.25rem' },
        infoValue: { color: '#343a40', fontWeight: '500' },
        sectionTitle: { fontSize: '1.25rem', color: '#343a40', marginBottom: '0.5rem' },
        tabContainer: { display: 'flex', borderBottom: '1px solid #dee2e6', marginBottom: '1.5rem' },
        tabButton: (isActive) => ({
            padding: '0.75rem 1.25rem', background: 'none', border: 'none', cursor: 'pointer',
            fontSize: '1rem', color: isActive ? '#007bff' : '#495057', fontWeight: isActive ? '600' : '400',
            borderBottom: `3px solid ${isActive ? '#007bff' : 'transparent'}`, marginBottom: '-1px'
        }),
    };

    const renderTabContent = () => {
        switch(activeTab) {
            case 'Base Allocation': return <BaseAllocationTab />;
            case 'Per-group Allocation': return <PlaceholderTab title="Per-group Allocation" />;
            case 'Per-delivery Allocation': return <PlaceholderTab title="Per-delivery Allocation" />;
            case 'Staff Roles': return <PlaceholderTab title="Staff Roles" />;
            case 'Per-student Allocation': return <PlaceholderTab title="Per-student Allocation" />;
            case 'Activity Allocation': return <PlaceholderTab title="Activity Allocation" />;
            default: return null;
        }
    };

    return (
        <div style={styles.container}>
            <header style={styles.header}>
                <button style={styles.backButton} onClick={onBack} title="Back to list"><BackIcon /></button>
                <h1 style={styles.pageTitle}>{pageTitle}</h1>
            </header>
            <main style={styles.mainContent}>
                <div style={styles.stepperContainer}>
                    <div style={styles.stepper}>
                        <div style={styles.stepperLine}></div>
                        <div style={styles.stepperStep}>
                            <div style={styles.stepperCircle(true)}><div style={styles.stepperInnerCircle}></div></div>
                            <span style={styles.stepperLabel(true)}>Subject Workload</span>
                        </div>
                        <div style={styles.stepperStep}>
                            <div style={styles.stepperCircle(false)}></div>
                            <span style={styles.stepperLabel(false)}>Workload Distribution</span>
                        </div>
                    </div>
                </div>
                <div style={styles.contentArea}>
                    <div style={styles.infoCard}>
                        <h2 style={styles.sectionTitle}>Subject Info</h2>
                        <div style={styles.infoGrid}>
                            <div style={styles.infoItem}><span style={styles.infoLabel}>Subject Code</span><span style={styles.infoValue}>{subject.subjectCode}</span></div>
                            <div style={styles.infoItem}><span style={styles.infoLabel}>Version</span><span style={styles.infoValue}>{subject.version}</span></div>
                            <div style={styles.infoItem}><span style={styles.infoLabel}>Subject Name</span><span style={styles.infoValue}>{subject.subjectName}</span></div>
                            <div style={styles.infoItem}><span style={styles.infoLabel}>Date</span><span style={styles.infoValue}>{subject.date}</span></div>
                            <div style={styles.infoItem}><span style={styles.infoLabel}>Term</span><span style={styles.infoValue}>{subject.term}</span></div>
                            <div style={styles.infoItem}><span style={styles.infoLabel}>Format of delivery</span><span style={styles.infoValue}>{subject.formatOfDelivery}</span></div>
                            <div style={styles.infoItem}><span style={styles.infoLabel}>Subject Coordinator</span><span style={styles.infoValue}>{subject.subjectCoordinator}</span></div>
                        </div>
                    </div>
                    <div style={styles.infoCard}>
                        <h2 style={styles.sectionTitle}>Subject Workload Summary</h2>
                        <div style={styles.infoGrid}>
                            <div style={styles.infoItem}><span style={styles.infoLabel}>Total Subject Workload</span><span style={styles.infoValue}>{subject.summary.total_subject_workload}</span></div>
                            <div style={styles.infoItem}><span style={styles.infoLabel}>Total EFTSL for Subject</span><span style={styles.infoValue}>{subject.summary.total_eftsl_for_subject}</span></div>
                            <div style={styles.infoItem}><span style={styles.infoLabel}>Total administrative loadings for Subject</span><span style={styles.infoValue}>{subject.summary.total_administrative_loadings}</span></div>
                        </div>
                    </div>
                    <div style={styles.tabContainer}>
                        {tabs.map(tab => (
                            <button key={tab} style={styles.tabButton(activeTab === tab)} onClick={() => setActiveTab(tab)}>
                                {tab}
                            </button>
                        ))}
                    </div>
                    <div>
                        {renderTabContent()}
                    </div>
                </div>
            </main>
        </div>
    );
}

